pub(crate) fn spt_prim(mut prims: &mut crate::port::Cells, kind: i32, cx: i32, cy: i32, rx: i32, ry: i32, ink: i32, rgb: i32, flags: i32, stroke: i32) -> i32 {
    let r: i32 = pm_new(prims, 1, cx - rx, cy - ry, cx + rx, cy + ry, kind);
    pm_set(prims, r, pmf_cx(), cx);
    pm_set(prims, r, pmf_cy(), cy);
    pm_set(prims, r, pmf_rx(), rx);
    pm_set(prims, r, pmf_ry(), ry);
    pm_set(prims, r, pmf_ink(), ink);
    pm_set(prims, r, pmf_color(), rgb);
    pm_set(prims, r, pmf_conf(), 900);
    pm_set(prims, r, pmf_flags(), flags);
    pm_set(prims, r, pmf_stroke(), stroke);
    return r;
}
