#[test]
fn test_a_line_wholly_inside_a_kept_seal_is_not_body_text() {
    let cand: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ow: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ol: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let scr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    while crate::port::cells_len(cand) < 16 {
        crate::port::cells_push(cand, 0);
    }
    crate::port::cells_set(cand, 0, 1);
    crate::port::cells_set(cand, 8, 1000);
    crate::port::cells_set(cand, 9, 1000);
    crate::port::cells_set(cand, 10, 7000);
    crate::port::cells_set(cand, 11, 7000);
    crate::port::cells_set(cand, 15, -2);
    spt_oword(ow, 4000, 4000);
    spt_oword(ow, 4000, 4500);
    spt_oword(ow, 30000, 4000);
    spt_oword(ow, 30000, 30000);
    ol_new(ol, 1, 3700, 3800, 4300, 4200, 3700, 4200, 4300, 4200, 0, 0, 0, 1);
    ol_new(ol, 1, 3700, 4300, 30300, 4700, 3700, 4700, 30300, 4700, 0, 0, 1, 2);
    ol_new(ol, 1, 29700, 29800, 30300, 30200, 29700, 30200, 30300, 30200, 0, 0, 3, 1);
    while crate::port::cells_len(scr) < (sc_sel_base() + 8) {
        crate::port::cells_push(scr, 0);
    }
    crate::port::cells_set(scr, sc_sel_base(), 0);
    crate::port::cells_set(scr, sc_sel_base() + 1, 1);
    crate::port::cells_set(scr, sc_sel_base() + 2, 2);
    crate::testport::assert_eq(sx_drop_lines(scr, 3, ol, ow, cand), 2, "the line in the ring is out; the line that runs from the ring across the page and the line elsewhere stay");
    crate::testport::assert_eq(crate::port::cells_at(scr, sc_sel_base()), 1, "the first left is the second line");
    crate::testport::assert_eq(crate::port::cells_at(scr, sc_sel_base() + 1), 2, "then the third");
    crate::port::cells_set(cand, 15, -1);
    crate::port::cells_set(scr, sc_sel_base(), 0);
    crate::port::cells_set(scr, sc_sel_base() + 1, 1);
    crate::port::cells_set(scr, sc_sel_base() + 2, 2);
    crate::testport::assert_eq(sx_drop_lines(scr, 3, ol, ow, cand), 3, "a candidate whose reading was not kept takes nothing out of the body");
}
